'use strict';
const FEATURES={stepFree:'턱 없는 출입구',ramp:'경사로',elevator:'엘리베이터',nursing:'수유실',changing:'기저귀 교환대'};
const STATUS={good:'진입 가능',partial:'일부 가능',hard:'진입 어려움'};
const SEEDS=[
 {id:'demo1',name:'초록뜰 카페',category:'카페',address:'서울 성동구 서울숲길 · 예시 장소',lat:37.5451,lng:127.0415,features:['stepFree','ramp','changing'],status:'good',note:'예시 메모: 출입구에 턱이 없고 유모차를 놓을 공간이 있어요. 모든 예시 정보는 실제 시설과 무관합니다.'},
 {id:'demo2',name:'서울숲 가족센터',category:'공공시설',address:'서울 성동구 성수동 · 예시 장소',lat:37.5423,lng:127.0431,features:['stepFree','ramp','elevator','nursing','changing'],status:'good',note:'예시 메모: 엘리베이터와 수유실이 있는 시설입니다.'},
 {id:'demo3',name:'소담 식탁',category:'식당',address:'서울 성동구 왕십리로 · 예시 장소',lat:37.5468,lng:127.0444,features:['ramp'],status:'partial',note:'예시 메모: 이동식 경사로는 직원의 도움이 필요해요. 방문 전 확인이 필요합니다.'},
 {id:'demo4',name:'우리 아이 의원',category:'병원',address:'서울 성동구 뚝섬로 · 예시 장소',lat:37.5436,lng:127.0475,features:['stepFree','elevator','changing'],status:'good',note:'예시 메모: 엘리베이터를 이용해 진입할 수 있어요.'},
 {id:'demo5',name:'골목 커피',category:'카페',address:'서울 성동구 성수일로 · 예시 장소',lat:37.548,lng:127.0471,features:[],status:'hard',note:'예시 메모: 입구 계단이 있어 유모차와 휠체어 진입이 어려워요.'}
].map(p=>({...p,demo:true,date:null}));
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function readState(){try{const s=JSON.parse(localStorage.getItem('modu-entrance-v1')||'null');if(s&&Array.isArray(s.places)&&Array.isArray(s.favorites)&&s.votes&&typeof s.votes==='object')return s;}catch{}return {places:[],favorites:[],votes:{},points:0};}
let state=readState(), selected=new Set(), onlyFavorites=false, activeId=null, map, layer, toastTimer, picking=false, draftMarker;
function persist(next){try{localStorage.setItem('modu-entrance-v1',JSON.stringify(next));state=next;return true;}catch{toast('저장 공간이 부족하거나 저장이 제한되어 있어요. 브라우저 설정을 확인해 주세요.');return false;}}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4000);}
function places(){return [...state.places,...SEEDS];}
function filtered(){const q=$('#search').value.trim().toLowerCase();return places().filter(p=>(!q||`${p.name} ${p.address} ${p.category}`.toLowerCase().includes(q))&&(!$('#category').value||p.category===$('#category').value)&&[...selected].every(f=>p.features.includes(f))&&(!onlyFavorites||state.favorites.includes(p.id)));}
function tagHTML(p){return p.features.map(f=>`<span class="tag">${FEATURES[f]}</span>`).join('');}
function render(){const results=filtered();$('#count').textContent=results.length;$('#points').textContent=`${state.points||0} 포인트`;$('#badge').textContent=state.places.length>=3?'동네 길잡이 배지 🌿':state.places.length?'첫 제보 배지 🌱':'첫 제보를 기다리고 있어요';$('#favorites').setAttribute('aria-pressed',String(onlyFavorites));
 $('#list').innerHTML=results.length?results.map(p=>`<article class="place-card"><button class="card-main" data-id="${esc(p.id)}"><div class="card-top"><span>${esc(p.category)}${state.favorites.includes(p.id)?' · ♥':''}</span><span class="status ${p.status}">${STATUS[p.status]}</span></div><h3>${esc(p.name)}</h3><p class="address">${esc(p.address)}</p><div class="tags">${tagHTML(p)||'<span class="tag">확인된 편의시설 없음</span>'}</div><div class="verified">${p.demo?'체험용 예시 · 현장 확인 필요':`제보일 ${esc(p.date)}`} ${state.votes[p.id]?.type==='changed'?'· 변경 제보 있음':''}</div></button></article>`).join(''):'<div class="empty">조건에 맞는 장소가 아직 없어요.<br>필터를 줄이거나 직접 제보해 주세요.<br><button id="empty-report">장소 제보하기</button></div>';
 $('#list').querySelectorAll('[data-id]').forEach(el=>el.onclick=()=>openDetail(el.dataset.id));$('#empty-report')?.addEventListener('click',openReport);
 if(layer){layer.clearLayers();results.forEach(p=>{const marker=L.marker([p.lat,p.lng],{icon:L.divIcon({className:'',html:`<div class="pin ${p.status}"><span>${p.status==='hard'?'!':'✓'}</span></div>`,iconSize:[34,34],iconAnchor:[17,34]}),title:p.name,alt:p.name,keyboard:true}).addTo(layer);marker.on('click',()=>openDetail(p.id));});}
}
function openDetail(id){const p=places().find(p=>p.id===id);if(!p)return;activeId=id;const vote=state.votes[id];const validPhoto=typeof p.photo==='string'&&/^data:image\/(jpeg|png|webp);base64,/.test(p.photo);$('#detail-body').innerHTML=`<div class="dialog-heading"><div><span class="status ${p.status}">${STATUS[p.status]}</span><h2>${esc(p.name)}</h2></div><button class="close" data-close="detail" aria-label="닫기">×</button></div><p class="detail-address">${esc(p.category)} · ${esc(p.address)}</p>${validPhoto?`<img class="photo" src="${esc(p.photo)}" alt="${esc(p.name)} 출입구 제보 사진">`:'<div class="photo-placeholder"><span aria-hidden="true">▧</span>아직 등록된 출입구 사진이 없어요</div>'}<div class="facility-grid">${Object.entries(FEATURES).map(([key,label])=>`<div class="facility ${p.features.includes(key)?'':'off'}">${p.features.includes(key)?'✓':'?'} ${label}${p.features.includes(key)?'':' · 미확인'}</div>`).join('')}</div><div class="note">${esc(p.note||'등록된 방문 메모가 없어요.')}</div><p class="muted">${p.demo?'이 장소는 기능을 체험하기 위한 가상 장소입니다.':`제보일: ${esc(p.date)} · 다른 이용자의 검증이 필요해요.`}<br>${vote?`이 브라우저의 최근 확인: ${esc(vote.date)} · ${vote.type==='accurate'?'정확해요':'정보가 바뀌었어요'}`:'아직 이 브라우저에서 확인하지 않은 정보예요.'}</p><div class="actions"><button id="save-place">${state.favorites.includes(id)?'♥ 저장됨':'♡ 즐겨찾기'}</button><button id="accurate">✓ 정확해요</button><button id="changed">정보가 바뀌었어요</button></div><p class="muted">방문 전 사진과 최신 정보를 직접 확인해 주세요.</p>`;
 $('#save-place').onclick=()=>{const favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];if(persist({...state,favorites})){render();openDetail(id);}};
 $('#accurate').onclick=()=>verify(id,'accurate');$('#changed').onclick=()=>verify(id,'changed');bindClose();if(!$('#detail').open)$('#detail').showModal();if(map)map.panTo([p.lat,p.lng]);
}
function today(){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
function verify(id,type){const existing=state.votes[id];if(existing?.type===type){toast('이미 확인한 정보예요.');return;}const next={...state,votes:{...state.votes,[id]:{type,date:today()}},points:(state.points||0)+(existing?0:10)};if(persist(next)){render();openDetail(id);toast(existing?'확인 내용을 수정했어요.':'확인해 주셔서 고마워요! +10P');}}
function bindClose(){document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.close).close());}
function openReport(){if(picking){picking=false;}$('#form-error').textContent='';$('#report-dialog').showModal();}
async function photoData(file){if(!file)return null;if(file.size>5*1024*1024)throw new Error('사진은 5MB 이하로 선택해 주세요.');if(!file.type.startsWith('image/'))throw new Error('이미지 파일을 선택해 주세요.');const url=URL.createObjectURL(file);try{const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(new Error('사진을 읽을 수 없어요. JPG 또는 PNG로 다시 선택해 주세요.'));img.src=url;});const canvas=document.createElement('canvas');const scale=Math.min(1,1000/Math.max(img.width,img.height));canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',.75);}finally{URL.revokeObjectURL(url);}}
$('#filters').innerHTML=Object.entries(FEATURES).map(([key,label])=>`<button class="filter" data-feature="${key}" aria-pressed="false">${label}</button>`).join('');
$('#report-features').innerHTML=Object.entries(FEATURES).map(([key,label])=>`<label><input type="checkbox" name="features" value="${key}">${label}</label>`).join('');
$('#filters').querySelectorAll('button').forEach(b=>b.onclick=()=>{selected.has(b.dataset.feature)?selected.delete(b.dataset.feature):selected.add(b.dataset.feature);b.setAttribute('aria-pressed',String(selected.has(b.dataset.feature)));render();});
$('#search').oninput=render;$('#category').onchange=render;$('#favorites').onclick=()=>{onlyFavorites=!onlyFavorites;render();};
function resetFilters(){selected.clear();onlyFavorites=false;$('#search').value='';$('#category').value='';$('#filters').querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed','false'));render();}
$('#reset').onclick=resetFilters;$('#report').onclick=openReport;bindClose();
$('#pick-location').onclick=()=>{if(!map){toast('지도를 불러올 수 없어 위도와 경도를 직접 입력해 주세요.');return;}picking=true;$('#report-dialog').close();$('#map').scrollIntoView({behavior:'smooth',block:'center'});toast('지도에서 장소의 위치를 눌러 주세요.');};
$('#report-form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('[type=submit]');button.disabled=true;$('#form-error').textContent='';try{const data=new FormData(form),name=data.get('name').trim(),address=data.get('address').trim();if(!name||!address)throw new Error('장소 이름과 주소를 입력해 주세요.');const photo=await photoData(form.elements.photo.files[0]);const p={id:crypto.randomUUID(),name,address,category:data.get('category'),lat:Number(data.get('lat')),lng:Number(data.get('lng')),features:data.getAll('features'),status:data.get('status'),note:data.get('note').trim(),date:today(),photo,demo:false};if(!Number.isFinite(p.lat)||!Number.isFinite(p.lng)||Math.abs(p.lat)>90||Math.abs(p.lng)>180)throw new Error('올바른 위도와 경도를 입력해 주세요.');if(!persist({...state,places:[p,...state.places],points:(state.points||0)+50}))return;$('#report-dialog').close();form.reset();if(draftMarker){draftMarker.remove();draftMarker=null;}resetFilters();if(map)map.setView([p.lat,p.lng],16);openDetail(p.id);toast('제보가 저장됐어요. 고마워요! +50P');}catch(error){$('#form-error').textContent=error.message||'제보를 저장하지 못했어요.';}finally{button.disabled=false;}};
if(window.L){try{map=L.map('map',{zoomControl:false}).setView([37.5451,127.044],15);L.control.zoom({position:'topright'}).addTo(map);const tiles=L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'}).addTo(map);tiles.on('tileerror',()=>{$('#map-error').hidden=false;});layer=L.layerGroup().addTo(map);map.on('click',e=>{if(!picking)return;picking=false;const form=$('#report-form');form.elements.lat.value=e.latlng.lat.toFixed(6);form.elements.lng.value=e.latlng.lng.toFixed(6);if(draftMarker)draftMarker.remove();draftMarker=L.marker(e.latlng).addTo(map);openReport();});}catch{$('#map-error').hidden=false;}}else{$('#map-error').hidden=false;}
render();
